"""Assemble REPORT.md = narrative (this file) + tables regenerated by analyze.py + judge summary + bench summary.

Usage: python build_report.py   (writes ../REPORT.md; sections whose inputs are missing are marked PENDING)
"""

from __future__ import annotations

import json
import pathlib
import statistics
import subprocess
import sys

HERE = pathlib.Path(__file__).resolve().parent
LANE = HERE.parent
PY = sys.executable

NARRATIVE = LANE / "REPORT_NARRATIVE.md"


def tables() -> str:
    out = subprocess.run([PY, str(HERE / "analyze.py")], capture_output=True, text=True, cwd=HERE)
    return out.stdout


def judge_summary() -> str:
    rows = []
    for f in sorted(HERE.glob("judge/judge_*.jsonl")):
        model = f.stem.replace("judge_", "")
        recs = [json.loads(line) for line in f.read_text().splitlines() if line.strip()]
        if not recs:
            continue
        p = [r["p_yes"] for r in recs]
        y = [1 if r["realized_progress"] else 0 for r in recs]
        n = len(p)
        pos = sum(y)
        # AUROC via rank statistic
        order = sorted(range(n), key=lambda i: p[i])
        ranks = [0.0] * n
        i = 0
        while i < n:
            j = i
            while j + 1 < n and p[order[j + 1]] == p[order[i]]:
                j += 1
            r = (i + j) / 2 + 1
            for k in range(i, j + 1):
                ranks[order[k]] = r
            i = j + 1
        neg = n - pos
        auroc = (
            (sum(ranks[i] for i in range(n) if y[i]) - pos * (pos + 1) / 2) / (pos * neg)
            if pos and neg
            else float("nan")
        )
        brier = sum((pi - yi) ** 2 for pi, yi in zip(p, y)) / n
        bins = [[] for _ in range(10)]
        for pi, yi in zip(p, y):
            bins[min(9, int(pi * 10))].append((pi, yi))
        ece = sum(
            len(b) / n * abs(statistics.mean(x[0] for x in b) - statistics.mean(x[1] for x in b)) for b in bins if b
        )
        abstain = sum(1 for pi in p if pi < 0.5) / n
        # gate value: realized progress rate among ticks the gate would PASS vs would HOLD
        passed = [yi for pi, yi in zip(p, y) if pi >= 0.5]
        held = [yi for pi, yi in zip(p, y) if pi < 0.5]
        rp = statistics.mean(passed) if passed else float("nan")
        rh = statistics.mean(held) if held else float("nan")
        if n >= 12855:
            complete = "yes (all 12,855 ticks)"
        elif n >= 12855 // 3:
            complete = f"stride-3 subsample ({n} of 12,855)"
        else:
            complete = f"partial {n}/12855"
        rows.append(
            f"| {model} | {n} | {pos / n:.1%} | {auroc:.3f} | {brier:.3f} | {ece:.3f} | {abstain:.0%} | {rp:.1%} | {rh:.1%} | {complete} |"
        )
    if not rows:
        return "PENDING (judge.py has not produced results yet)\n"
    head = (
        "| model | ticks judged | base rate (proposal did reduce distance) | AUROC | Brier | ECE-10 | gate@0.5 would hold "
        "| progress rate among PASSED | progress rate among HELD | complete |\n|---|---|---|---|---|---|---|---|---|---|\n"
    )
    return head + "\n".join(rows) + "\n"


def bench_summary() -> str:
    lines = []
    for f in sorted(HERE.glob("bench_*.log")):
        for line in f.read_text().splitlines():
            if " p50 " in line and "|" in line:
                m, dev, rest = line.split("|", 2)
                q, nums = rest.split(" p50 ")
                p50, p95 = nums.replace(" ms", "").split(" p95 ")
                lines.append(f"| {m} | {dev} | {q.strip()} | {p50.strip()} | {p95.strip()} |")
    if not lines:
        return "PENDING (bench_latency.py)\n"
    return "| model | device | questions | p50 ms | p95 ms |\n|---|---|---|---|---|\n" + "\n".join(lines) + "\n"


def main() -> None:
    narrative = NARRATIVE.read_text()
    body = (
        narrative.replace("<<TABLES>>", tables())
        .replace("<<JUDGE>>", judge_summary())
        .replace("<<BENCH>>", bench_summary())
        .replace(
            "<<VERDICTS>>",
            (LANE / "REPORT_VERDICTS.md").read_text()
            if (LANE / "REPORT_VERDICTS.md").exists()
            else "PENDING (written when all arms finish)\n",
        )
    )
    (LANE / "REPORT.md").write_text(body)
    print("wrote", LANE / "REPORT.md", len(body), "chars")


if __name__ == "__main__":
    main()
